const fillPromoWithLinkData = (info, promoLinkData) => {
  info.promo = info.promo.map(item => {
    promoLinkData.forEach(promo => {
      if (item.indexOf(promo.value) > -1 && (item.indexOf('.jd.com') === -1 || item.indexOf('item.jd.com/') > -1)) {
        item = item.replaceAll(':', '_').replaceAll(';', '_');
        if (item.indexOf(seprator) > -1) {
          item = item.split(seprator)[1];
        }
        if (promo.promoId) {
          item = `https://search.jd.com/Search?activity_id=${promo.promoId}&sku=${skuId}${seprator}${item}`;
        }
      }
    });
    return item;
  });
  if (promoLinkData.length && !info.promo.length) {
    info.promo = promoLinkData.map(promo => {
      const linkHTML = promo.link;
      if (!linkHTML) {
        return `${seprator}${promo.text}${seprator}${promo.value}`;
      }
      const isLink = linkHTML.startsWith('//');
      if (isLink) {
        return `${linkHTML}${seprator}${promo.text}${promo.value ? '--' : ''}${promo.value}`;
      }
      const link = linkHTML.match(/href='([^']+)'/);
      if (link && link[1]) {
        return `${link[1]}${seprator}${promo.text}${promo.value ? '--' : ''}${promo.value}`;
      }
      return `${seprator}${promo.text}${seprator}${promo.value}`;
    });
  }
};
const fillPromoWithCouponLinkData = (info, couponLinkData) => {
  info.quan = info.quan.map(item => {
    let stritem = item.toString();
    let theCoupon = null;
    couponLinkData.forEach(coupon => {
      if (coupon.value && !coupon.couponValue) {
        coupon.couponValue = coupon.value;
      }
      if (!coupon.batchId && coupon.preferenceId) {
        coupon.batchId = coupon.preferenceId;
      }
      if (stritem.indexOf(coupon.couponValue) > -1 && stritem.indexOf('.jd.com') === -1) {
        theCoupon = coupon;
        // item = `https://search.jd.com/Search?coupon_batch=${coupon.batchId}&sku=${skuId}:${item}`
        item = `${coupon.batchId}_${coupon.roleId}_${coupon.encryptedKey}${seprator}${stritem}`;
      }
      if ((stritem.indexOf(coupon.quota + '元减') > -1 || stritem.indexOf(coupon.quota + '减') > -1) && stritem.indexOf('.jd.com') === -1) {
        theCoupon = coupon;
        // item = `https://search.jd.com/Search?coupon_batch=${coupon.batchId}&sku=${skuId}:${item}`
        item = `${coupon.batchId}_${coupon.roleId}_${coupon.encryptedKey}${seprator}${stritem}`;
      }
    });
    if (theCoupon && new Date(theCoupon.beginTime + ' ' + theCoupon.beginHour) > new Date()) {
      return;
    }
    return item;
  }).filter(x => !!x && !x.includes('官方直降'));
};
