module.exports.requestXHR = function requestXHR(url, withCredentials = true, customHeaders = null) {
  if (G.serviceWorker) {
    return fetch(url, {
      "credentials": withCredentials ? "include" : ''
    }).then(r => r.text());
  }
  return new Promise(resolve => {
    var xmlhttp = new XMLHttpRequest();
    xmlhttp.addEventListener('load', function () {
      try {
        let res = JSON.parse(xmlhttp.responseText);
        resolve(res);
      } catch (e) {
        resolve(xmlhttp.responseText);
      }
    });
    xmlhttp.withCredentials = withCredentials;
    xmlhttp.open("GET", url, true);
    if (customHeaders) {
      Object.keys(customHeaders).forEach(key => {
        xmlhttp.setRequestHeader(key, customHeaders[key]);
      });
    }
    xmlhttp.send();
  });
};
module.exports.requestXHRPost = function requestXHR(url, data, form = true, withCredentials = true) {
  return new Promise(resolve => {
    let xmlhttp = new XMLHttpRequest();
    xmlhttp.addEventListener('load', function () {
      try {
        let res = JSON.parse(xmlhttp.responseText);
        resolve(res);
      } catch (e) {
        resolve(xmlhttp.responseText);
      }
    });
    xmlhttp.withCredentials = withCredentials;
    xmlhttp.open("POST", url, true);
    if (G.requestNeedToken) {
      //xmlhttp.setRequestHeader('x-bjg-token', G.requestNeedToken)
    }
    if (form) {
      let formData = new FormData();
      Object.keys(data).forEach(item => {
        formData.append(item, data[item]);
      });
      xmlhttp.send(formData);
    } else {
      xmlhttp.setRequestHeader('Content-Type', 'text/plain');
      xmlhttp.send(data);
    }
  });
};
